        "Geben Sie Ihre iOS- oder iPadOS-Version, das Gerätemodell und eine kurze Problembeschreibung an.",
        "Teilen Sie Playlist-Passwörter per E-Mail nur, wenn es für die Fehlersuche nötig ist."
